import pyomo.environ as pyo

DATA = {
    "containers": ["small", "large"],
    "water_per_container": {"small": 10, "large": 20},
    "powder_per_container": {"small": 15, "large": 20},
    "paste_per_container": {"small": 20, "large": 30},
    "water_available": 500,
    "powder_available": 700,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.CONTAINERS = pyo.Set(initialize=d["containers"])

    model.containers_used = pyo.Var(
        model.CONTAINERS,
        within=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(
            d["paste_per_container"][c] * m.containers_used[c]
            for c in m.CONTAINERS
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def water_rule(m):
        return sum(
            d["water_per_container"][c] * m.containers_used[c]
            for c in m.CONTAINERS
        ) <= d["water_available"]

    model.water_limit = pyo.Constraint(rule=water_rule)

    def powder_rule(m):
        return sum(
            d["powder_per_container"][c] * m.containers_used[c]
            for c in m.CONTAINERS
        ) <= d["powder_available"]

    model.powder_limit = pyo.Constraint(rule=powder_rule)

    return model


